  const [dateSearchText, setDateSearchText] = useState('');

  // Additional filter states
  const [additionalFilters, setAdditionalFilters] = useState([]);
  const [groupFilters, setGroupFilters] = useState({});
  const [segmentFilters, setSegmentFilters] = useState({});

  // Search text states
  const [originSearchText, setOriginSearchText] = useState('');
  const [destSearchText, setDestSearchText] = useState('');

  // Track selection changes with a ref to prevent race conditions
  const selectionRef = useRef({ start: null, end: null });

  // Sample raw response data for fallback
  const sampleRawData = useRef([
    {
      "originAirport": "LHR",
      "destinationAirport": "EWR",
      "date": "2025-03-28",
      "distance": 3459,
      "ID": "sample1",
      "source": "aeroplan",
      "YAvailable": true,
      "WAvailable": false,
      "JAvailable": true,
      "FAvailable": false,
      "YDirect": true,
      "WDirect": false,
      "JDirect": true,
      "FDirect": false,
      "YAirlines": "AC, LH, QK, UA",
      "WAirlines": "",
      "JAirlines": "UA",
      "FAirlines": "",
      "YDirectAirlines": "UA",
      "WDirectAirlines": "",
      "JDirectAirlines": "UA",
      "FDirectAirlines": "",
      "YMileageCost": "40000",
      "WMileageCost": "0",
      "JMileageCost": "80000",
      "FMileageCost": "0",
      "YTotalTaxes": 34639,
      "WTotalTaxes": 0,
      "JTotalTaxes": 55000,
      "FTotalTaxes": 0,
      "YDirectMileageCost": 40000,
      "WDirectMileageCost": 0,
      "JDirectMileageCost": 80000,
      "FDirectMileageCost": 0,
      "YDirectTotalTaxes": 35470,
      "WDirectTotalTaxes": 0,
      "JDirectTotalTaxes": 55000,
      "FDirectTotalTaxes": 0,
      "TaxesCurrency": "CAD"
    }
  ]);

  // Handle tooltip cleanup on window resize or scroll
  useEffect(() => {
    const handleWindowChange = () => {
      const tooltipId = activeTooltipRef.current;
      if (tooltipId) {
        const tooltip = document.getElementById(tooltipId);
        if (tooltip) {
          document.body.removeChild(tooltip);
          activeTooltipRef.current = null;
        }
      }
    };

    window.addEventListener('resize', handleWindowChange);
    window.addEventListener('scroll', handleWindowChange);

    return () => {
      window.removeEventListener('resize', handleWindowChange);
      window.removeEventListener('scroll', handleWindowChange);
    };
  }, []);

  // Clean up any tooltips when component unmounts
  useEffect(() => {
    return () => {
      const tooltipId = activeTooltipRef.current;
      if (tooltipId) {
        const tooltip = document.getElementById(tooltipId);
        if (tooltip && document.body.contains(tooltip)) {
          document.body.removeChild(tooltip);
        }
      }
    };
  }, []);

  // Calendar navigation - go to previous month
  const goToPrevMonth = () => {
    const { year, month } = getPreviousMonth(currentYear, currentMonth);
    setCurrentYear(year);
    setCurrentMonth(month);
    // Reset pagination when changing months
    setCellPages({});
  };

  // Calendar navigation - go to next month
  const goToNextMonth = () => {
    const { year, month } = getNextMonth(currentYear, currentMonth);
    setCurrentYear(year);
    setCurrentMonth(month);
    // Reset pagination when changing months
    setCellPages({});
  };

  // Handle date selection
  const handleDateClick = (dateString) => {
    // If we already have a full range, start a new selection
    if (localSelectionStart && localSelectionEnd) {
      setLocalSelectionStart(dateString);
      setLocalSelectionEnd(null);
      selectionRef.current = { start: dateString, end: null };
      return;
    }

    // If we have a start date but no end date
    if (localSelectionStart && !localSelectionEnd) {
      // Make sure end date is after start date
      const start = dayjs(localSelectionStart);
      const end = dayjs(dateString);

      if (end.isBefore(start)) {
        // If end is before start, swap them
        setLocalSelectionEnd(localSelectionStart);
        setLocalSelectionStart(dateString);
        selectionRef.current = { start: dateString, end: localSelectionStart };
      } else {
        // Normal case: end is after start
        setLocalSelectionEnd(dateString);
        selectionRef.current = { start: localSelectionStart, end: dateString };
      }

      // Notify parent component about selection
      if (onDateRangeSelect) {
        if (end.isBefore(start)) {
          onDateRangeSelect(dateString, localSelectionStart);
        } else {
          onDateRangeSelect(localSelectionStart, dateString);
        }
      }
    } else {
      // Starting a new selection
      setLocalSelectionStart(dateString);
      setLocalSelectionEnd(null);
      selectionRef.current = { start: dateString, end: null };
    }
  };

  // Page navigation for a specific date cell
  const handlePageChange = (dateString, direction, e) => {
    e.stopPropagation();  // Prevent the date cell click handler from firing

    const currentPage = cellPages[dateString] || 0;
    let newPage;

    if (direction === 'prev') {
      newPage = Math.max(0, currentPage - 1);
    } else {
      newPage = currentPage + 1;
    }

    setCellPages({
      ...cellPages,
      [dateString]: newPage
    });
  };

  // Check if a date should be rendered based on filters
  const shouldRenderDate = (dateString) => {
    // If no date filter active, render all dates
    if (dateFilter.length === 0) return true;

    // If date is in the filter list, render it
    return dateFilter.includes(dateString);
  };

  // Handle segment reordering
  const moveSegment = (segment, direction) => {
    const segments = getUniqueSegments(flightData);
    const sortedSegments = [...segments].sort(sortSegments);

    const currentIndex = sortedSegments.indexOf(segment);
    if (currentIndex === -1) return;

    let newIndex;
    if (direction === 'up' && currentIndex > 0) {
      newIndex = currentIndex - 1;
    } else if (direction === 'down' && currentIndex < sortedSegments.length - 1) {
      newIndex = currentIndex + 1;
    } else {
      return; // Can't move further
    }

    // Swap the positions in segmentOrder
    const updatedOrder = [...segmentOrder];

    // Add the segments to the order array if they're not already there
    if (!updatedOrder.includes(segment)) {
      updatedOrder.push(segment);
    }
    if (!updatedOrder.includes(sortedSegments[newIndex])) {
      updatedOrder.push(sortedSegments[newIndex]);
    }

    // Find their indices in the order array
    const orderIndex1 = updatedOrder.indexOf(segment);
    const orderIndex2 = updatedOrder.indexOf(sortedSegments[newIndex]);

    // Swap them
    [updatedOrder[orderIndex1], updatedOrder[orderIndex2]] = 
    [updatedOrder[orderIndex2], updatedOrder[orderIndex1]];

    setSegmentOrder(updatedOrder);
  };

  // Sorting function for segments based on custom order
  const sortSegments = (a, b) => {
    const indexA = segmentOrder.indexOf(a);
    const indexB = segmentOrder.indexOf(b);

    // If both have custom positions, use those
    if (indexA !== -1 && indexB !== -1) {
      return indexA - indexB;
    }

    // If only one has a custom position, prioritize it
    if (indexA !== -1) return -1;
    if (indexB !== -1) return 1;

    // Default sort by segment name
    return a.localeCompare(b);
  };

  // Get flights for a class with all filters applied
  const getFlightsForClassWithFilters = (route, classCode, dateString, classData) => {
    if (!classData) return [];

    // Get the enriched flight data with raw API information
    const rawDataArray = flightData?.rawData || sampleRawData.current;
    const enrichedFlights = getEnrichedFlightData(route, classCode, dateString, classData, rawDataArray);

    // Apply all the active filters
    return filterFlights(enrichedFlights, {
      segmentFilter,
      directFilter,
      sourceFilter,
      airlinesFilter,
      pointsFilter,
      segmentFilters,
      groupFilters
    });
  };

  // Create an enhanced tooltip for displaying flight details
  const createEnhancedTooltip = (classCode, flights, isDirect = false) => {
    // Remove any existing tooltip
    const existingTooltip = activeTooltipRef.current;
    if (existingTooltip) {
      const tooltip = document.getElementById(existingTooltip);
      if (tooltip) {
        document.body.removeChild(tooltip);
      }
    }

    // Create a new tooltip ID
    const tooltipId = `tooltip-${Date.now()}`;
    activeTooltipRef.current = tooltipId;

    // Create the tooltip element - this would typically use FlightTooltip component
    // but for encapsulation in this hook we'll return the tooltip ID and flights data
    return {
      tooltipId,
      flights: flights.slice(0, 10), // Limit to 10 flights for performance
      classCode,
      isDirect
    };
  };

  return {
    // State
    currentMonth,
    currentYear,
    localSelectionStart,
    localSelectionEnd,
    error,
    cellPages,
    activeTooltipRef,
    segmentFilter,
    classFilter,
    directFilter,
    sourceFilter,
    pointsFilter,
    airlinesFilter,
    dateFilter,
    additionalFilters,
    groupFilters,
    segmentFilters,
    segmentSearchText,
    sourceSearchText,
    airlinesSearchText,
    dateSearchText,
    originSearchText,
    destSearchText,

    // Setters
    setCurrentMonth,
    setCurrentYear,
    setLocalSelectionStart,
    setLocalSelectionEnd,
    setError,
    setCellPages,
    setSegmentFilter,
    setClassFilter,
    setDirectFilter,
    setSourceFilter,
    setPointsFilter,
    setAirlinesFilter,
    setDateFilter,
    setAdditionalFilters,
    setGroupFilters,
    setSegmentFilters,
    setSegmentSearchText,
    setSourceSearchText,
    setAirlinesSearchText,
    setDateSearchText,
    setOriginSearchText,
    setDestSearchText,

    // Methods
    goToPrevMonth,
    goToNextMonth,
    handleDateClick,
    handlePageChange,
    getFlightsForClassWithFilters,
    createEnhancedTooltip,
    shouldRenderDate,
    moveSegment,
    sortSegments,

    // Data accessors
    getUniqueSegments: () => getUniqueSegments(flightData),
    getUniqueSources: () => getUniqueSources(flightData),
    getUniqueAirlines: () => getUniqueAirlines(flightData),
